--
-- Decisao 03: colunas descritivas de aeroporto (nullable).
-- Os valores vem de silver.dim_airports no pipeline; aqui entram vazios,
-- e a API/frontend exibem a sigla quando o nome e' NULL.
--
ALTER TABLE `airport_performance`
  ADD COLUMN `airport_name` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL AFTER `airport`,
  ADD COLUMN `airport_city` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL AFTER `airport_name`,
  ADD COLUMN `airport_state` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL AFTER `airport_city`,
  ADD COLUMN `airport_label` varchar(70) COLLATE utf8mb4_unicode_ci DEFAULT NULL AFTER `airport_state`,
  ADD KEY `idx_airport_name` (`airport_name`),
  ADD KEY `idx_airport_city` (`airport_city`);

